        *gain = 0.0;
        *field_direction = (adcs_vec3_t){0.0, 0.0, 0.0};
        *scheduled_axis_gain = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

