    // Check for NULL pointers
    if ((field == NULL) || (gain == NULL) || (field_direction == NULL) || (scheduled_axis_gain == NULL)) {
        return ADCS_E_NULL;
    }

    // Check finiteness and range of scalar parameters
    if ((!isfinite(base_gain)) || (base_gain < 0.0) ||
        (!isfinite(reference_field)) || (reference_field <= 0.0) ||
        (!isfinite(min_gain)) || (min_gain < 0.0) ||
        (!isfinite(max_gain)) || (max_gain < min_gain)) {
        return ADCS_E_RANGE;
    }

    // Check if magnetic field vector is finite
    if (!adcs_is_finite_vec3(field)) {
        return ADCS_E_RANGE;
    }

    // Compute norm of the magnetic field
    double b = adcs_vec3_norm(field);

    // Check for degenerate case (zero or near-zero magnitude)
    if (b <= ADCS_EPS_NORM) {
        *gain = 0.0;
        field_direction->x = 0.0;
        field_direction->y = 0.0;
        field_direction->z = 0.0;
        scheduled_axis_gain->x = 0.0;
        scheduled_axis_gain->y = 0.0;
        scheduled_axis_gain->z = 0.0;
        return ADCS_E_DEGENERATE;
    }

    // Compute raw gain: g_raw = base_gain * (reference_field / b)^2
    double inv_b = 1.0 / b;
    double ratio = reference_field * inv_b;
    double g_raw = base_gain * ratio * ratio;

    // Clamp gain: gain = clamp(g_raw, min_gain, max_gain)
    double gain_val = ADCS_CLAMP(g_raw, min_gain, max_gain);

    // Normalize field direction: field_direction = B / b
    field_direction->x = field->x * inv_b;
    field_direction->y = field->y * inv_b;
    field_direction->z = field->z * inv_b;

    // Compute scheduled axis gain: scheduled_axis_gain = gain * field_direction
    scheduled_axis_gain->x = gain_val * field_direction->x;
    scheduled_axis_gain->y = gain_val * field_direction->y;
    scheduled_axis_gain->z = gain_val * field_direction->z;

    // Store final gain value
    *gain = gain_val;

    return ADCS_OK;
}

